const {fitDataAsync, OPTIMIZERS} = DataScience;
const {vec} = NMath;
// Fewer turns make the spiral easy to learn with a small network.
const {x: spiral} = IO.loadSpiralData({turns: 0.5});
const targets = spiral;
const bounds = [0, 1].map(axis => [
    Math.min(...spiral.map(point => point.components[axis])),
    Math.max(...spiral.map(point => point.components[axis])),
]);
const randomPoint = () => vec(...bounds.map(([min, max]) => min + Math.random() * (max - min)));

// For independent source and target samples, the straight path has velocity x1 - x0.
const samples = Array.from({length: 12000}, () => {
    const x0 = randomPoint();
    const x1 = targets[Math.floor(Math.random() * targets.length)];
    const t = Math.random();
    return {
        input: vec(...x0.scale(1 - t).add(x1.scale(t)).components, t),
        velocity: x1.sub(x0),
    };
});

// One symbolic neural network predicts the 2D time-dependent vector field.
const field = NeuralNet.builder()
    .input(3)
    .layer(24)
    .layer(24)
    .layer(2, NeuralNet.ACTIVATIONS.linear)
    .build();

const initial = Array.from({length: 400}, randomPoint);
// Keep the target cloud visible in gray, behind the moving samples.
const plot = IO.plotPointCloud(targets, {aspect: "equal", radius: 0.012, color: [0.4, 0.4, 0.4]});
const moving = plot.add(initial, {radius: 0.015, color: [1, 0, 0]});
const arrows = plot.addLines([], {color: [0.35, 0.65, 1]});
// Invisible anchors keep the coordinate system fixed as the cloud moves.
plot.add([[-1.2, -1.2], [1.2, 1.2]], {color: [0, 0, 0]});
const steps = 100;
let trajectory;

// Draw velocity arrows on a fixed grid, with their length capped to limit overlap.
const fieldLines = t => {
    const lines = [];
    for (let x = -1; x <= 1; x += 0.25) {
        for (let y = -1; y <= 1; y += 0.25) {
            const start = vec(x, y);
            const velocity = vec(...field.eval(vec(x, y, t)));
            const length = velocity.length();
            if (length < 1e-8) continue;
            const delta = velocity.scale(Math.min(0.1, 0.14 / length));
            const end = start.add(delta);
            const [dx, dy] = delta.components;
            const head = delta.scale(0.3);
            const side = vec(-dy, dx).scale(0.15);
            lines.push([start, end], [end, end.sub(head).add(side)], [end, end.sub(head).sub(side)]);
        }
    }
    return lines;
};

const showTime = t => {
    if (!trajectory) return;
    moving.update(trajectory[Math.round(t * steps)], {color: [1 - t, t, 0]});
    arrows.update(fieldLines(t));
    plot.render();
};

const ui = IO.UI(
    {type: "canvas", value: () => plot},
    {type: "slider", value: () => ({
        title: "t:", min: 0, max: 1, step: 1 / steps, value: 0,
        onChange: showTime,
    })},
);

// Train on random path positions and their known vector velocities using squared error.
const {theta} = await fitDataAsync(
    samples.map(sample => sample.input),
    samples.map(sample => sample.velocity),
    field.model,
    {
        epochs: 5000,
        batch: 32,
        optimizer: OPTIMIZERS.ADAMW({learningRate: 0.005}),
        continuationEvery: 250,
        continuationFn: ({epoch, loss}) => console.log(`Epoch ${epoch + 1}, loss ${loss.toFixed(4)}`),
    },
);
field.setWeights(theta);

// Integrate from the same starting points once; slider changes can then move both ways.
trajectory = [initial];
for (let step = 0; step < steps; step++) {
    const t = step / steps;
    trajectory.push(trajectory[step].map(point => {
        const input = vec(...point.components, t);
        const velocity = vec(...field.eval(input));
        return point.add(velocity.scale(1 / steps));
    }));
}
showTime(0);
ui;
